-- OpenLua - OneLua game module demo (read-only PBP subset).
--
--   local info = game.info(path)       -- PARAM.SFO fields, or nil
--   local icon = game.geticon0(path)   -- 144x80 ICON0, or nil
--   local pic0 = game.getpic0(path)    -- 310x180 PIC0, or nil
--   local pic1 = game.getpic1(path)    -- 480x272 PIC1, or nil
--
-- The images are normal image handles and use the usual image.* functions.
-- This demo reads the synthetic fixture generated by tools/gen_pbp.py.
-- Pack/add/remove/unpack/launch are intentionally not exposed, and only PBP
-- files are parsed; ISO/CSO support is still on the roadmap.

local path = "assets/sample.pbp"
local info = game.info(path)
local icon0 = game.geticon0(path)
local pic0 = game.getpic0(path)
local pic1 = game.getpic1(path)

local f = font.new("assets/font.png", 8, 16)
if f then
    screen.font(f)
end

local white = color.new(238, 240, 246)
local muted = color.new(120, 132, 154)
local teal  = color.new(48, 180, 160)
local amber = color.new(235, 180, 70)
local red   = color.new(230, 96, 96)
local dark  = color.new(10, 14, 26)

local function field(key)
    if not info or info[key] == nil then
        return "-"
    end
    return tostring(info[key])
end

local function image_size(img)
    if not img then
        return "nil"
    end
    return image.getw(img) .. "x" .. image.geth(img)
end

if pic1 then
    image.scale(pic1, 0.45)
    image.zindex(pic1, 1)
end
if pic0 then
    image.scale(pic0, 0.5)
    image.zindex(pic0, 1)
end

while true do
    screen.clear(dark)
    draw.fillrect(0, 0, 480, 4, teal)
    draw.fillrect(0, 268, 480, 4, amber)

    if f then
        screen.print(20, 10, "game.info / PBP metadata", f, white)
        screen.print(20, 36, "TITLE    " .. field("TITLE"), f, white)
        screen.print(20, 56, "TITLE_ID " .. field("TITLE_ID"), f, teal)
        screen.print(20, 76, "CATEGORY " .. field("CATEGORY"), f, muted)
        screen.print(20, 96, "APP_VER  " .. field("APP_VER"), f, muted)
        screen.print(20, 116, "PARENTAL " .. field("PARENTAL_LEVEL"), f, muted)
        screen.print(20, 136, "BOOTABLE " .. field("BOOTABLE"), f, muted)

        screen.print(20, 158, "ICON0 " .. image_size(icon0), f, teal)
        screen.print(252, 12, "assets/sample.pbp", f, muted)
        screen.print(252, 252, "pack/add/remove/launch: off", f, muted)
    end

    if icon0 then
        image.blit(icon0, 20, 176)
    end
    if pic1 then
        image.blit(pic1, 252, 34)
    end
    if pic0 then
        image.blit(pic0, 252, 160)
    end

    screen.flip()
end
